{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound gatherings and private sessions</title>
  <meta name="description" content="Group sound events and private sessions—gentle structure for clarity, intention, and rest in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-home">
  <a class="skip" href="#main">Skip to content</a>
  <header class="site-header">
    <div class="wrap">
      <div class="brand">
        <svg width="48" height="48" viewBox="0 0 100 100" aria-hidden="true"><use href="#logo-wave"/></svg>
        <div>
          <strong class="name">{{BUSINESS_NAME}}</strong>
          <div class="tag">{{TAGLINE}}</div>
        </div>
      </div>
      <nav class="main-nav" aria-label="Primary">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Care</a>
        <a href="/pricing.html">Packages</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="btn-cta">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main id="main">
    <section class="hero reveal" data-reveal>
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Gather with sound to clarify the edges of your day</h1>
          <p class="lead">Join short-form group sessions or focused private time to set an intention, unwind, or reorient. Gentle structure, clear transitions.</p>
          <div class="hero-ctas">
            <a href="/events.html" class="btn">Explore gatherings</a>
            <button id="tryNowBtn" class="btn ghost">Try a short exercise</button>
            <a href="{{PRIMARY_CTA_URL}}" class="btn solid">{{PRIMARY_CTA_LABEL}}</a>
          </div>
          <p class="disclaimer">Contraindications: If you have epilepsy, severe cardiovascular conditions, are pregnant, or have concerns about resonance and vibration, consult a healthcare provider before attending. If you use implanted medical devices, check with your clinician.</p>
        </div>
        <div class="hero-preview">
          <div class="next-event card" id="nextEvent">
            <h3>Upcoming gathering</h3>
            <div id="nextEventContent">
              <!-- populated by JS: next event summary -->
            </div>
            <a href="/events.html" class="link">Full schedule</a>
          </div>
        </div>
      </div>
    </section>

    <section class="diagnostic reveal" data-reveal>
      <div class="wrap">
        <h2>Find the right session for your intention</h2>
        <p>Answer a few quick prompts and we’ll point you to the right offering — a communal session, a private recalibration, or a short attunement to take home.</p>
        <div class="choices">
          <button class="choice" data-choice="reset">I need an emotional reset</button>
          <button class="choice" data-choice="focus">I want clearer focus</button>
          <button class="choice" data-choice="sleep">Preparing for sleep</button>
        </div>
        <div id="diagnosticResult" class="diagnostic-result" aria-live="polite"></div>
      </div>
    </section>

    <section class="plan reveal" data-reveal>
      <div class="wrap">
        <h2>Programs and how they work</h2>
        <div class="plan-grid">
          <article class="card">
            <h3>Community Series</h3>
            <p>60-minute group gatherings designed as a sequence: arrival, guided focus, sound immersion, gentle return. No experience required.</p>
            <a href="/events.html" class="link">See upcoming dates</a>
          </article>

          <article class="card">
            <h3>Focused Session</h3>
            <p>30‑40 minute private sessions tailored to intention — clarity, recovery, or guided rest. Solo work with space and attention.</p>
            <a href="/private-sessions.html" class="link">Book private time</a>
          </article>

          <article class="card">
            <h3>Season Pass</h3>
            <p>A pass for regular attendees: priority booking and a small credit towards private sessions. Good for ongoing practice.</p>
            <a href="/pricing.html" class="link">View options</a>
          </article>
        </div>
      </div>
    </section>

    <section class="micro-habits reveal" data-reveal>
      <div class="wrap">
        <h2>Daily signals you can use</h2>
        <p>Micro-habits—two minutes of breath, a one-line journal prompt, or a soft bell to mark a switch—build a steady foundation.</p>
        <ul class="habits">
          <li><strong>Two slow breaths</strong> — inhale 4s, exhale 6s. Repeat twice.</li>
          <li><strong>One-line check-in</strong> — jot a sentence: Where is attention now?</li>
          <li><strong>Shift bell</strong> — a small waypoint to end a task and start another.</li>
        </ul>
      </div>
    </section>

    <section class="pricing reveal" data-reveal>
      <div class="wrap">
        <h2>Packages framed for practice</h2>
        <p>Options are named for how they support you: Trial, Rhythm, and Steward. Find the cadence that fits your life.</p>
        <div class="pricing-grid">
          <div class="price card">
            <h3>Trial Drop-in</h3>
            <div class="amount">$18</div>
            <p>Single visit to test the format and vibe.</p>
            <a href="/pricing.html" class="link">Choose this</a>
          </div>
          <div class="price card highlight">
            <h3>Rhythm Pass</h3>
            <div class="amount">$140 / month</div>
            <p>Two sessions a month + reduced private session rates.</p>
            <a href="/pricing.html" class="link">Get the pass</a>
          </div>
          <div class="price card">
            <h3>Steward Bundle</h3>
            <div class="amount">$480</div>
            <p>Ten-session bundle for steady practice and shared booking.</p>
            <a href="/pricing.html" class="link">Buy bundle</a>
          </div>
        </div>
      </div>
    </section>

    <section class="cta reveal" data-reveal>
      <div class="wrap cta-wrap">
        <h2>Reserve a moment</h2>
        <p>Drop into a group or book focused time for personal attention.</p>
        <div class="cta-actions">
          <a href="/book.html" class="btn solid">Schedule a session</a>
          <a href="/contact.html" class="btn ghost">Contact team</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <div>{{CITY}}, {{STATE}}</div>
          <div class="contact">Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
        <nav aria-label="Footer">
          <a href="/events.html">Gatherings</a>
          <a href="/private-sessions.html">Private</a>
          <a href="/faq.html">FAQ</a>
          <a href="/about.html">About</a>
        </nav>
      </div>
      <small>Contraindications: Sound and vibration are not recommended without professional clearance for certain medical conditions. If you have implants, seizures, or pregnancy-related concerns, consult a clinician before attending.</small>
    </div>
  </footer>

  <!-- guided exercise modal -->
  <div id="exerciseModal" class="modal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="exerciseTitle">
    <div class="modal-shell">
      <button class="modal-close" id="exerciseClose" aria-label="Close exercise">×</button>
      <h2 id="exerciseTitle">Try a brief practice</h2>
      <p class="modal-desc">Choose a short guided moment: Breath cycle, one-line journaling, or intention setting. No audio required.</p>
      <div class="modal-controls">
        <button class="exercise-option" data-mode="breath">Breathing (2 minutes)</button>
        <button class="exercise-option" data-mode="journal">One-line journal (3 prompts)</button>
        <button class="exercise-option" data-mode="intention">Intention setting (guided)</button>
      </div>
      <div id="exerciseArea" class="exercise-area" aria-live="polite"></div>
      <div class="modal-actions">
        <button id="exerciseStart" class="btn solid">Start</button>
        <button id="exerciseCancel" class="btn ghost">Close</button>
      </div>
    </div>
  </div>

  <!-- SVG definitions for logo and pattern -->
  <svg style="position:absolute;width:0;height:0;overflow:hidden;" aria-hidden="true">
    <defs>
      <symbol id="logo-wave" viewBox="0 0 100 100">
        <rect width="100" height="100" rx="14" fill="#efeef6"></rect>
        <g fill="none" stroke="#6d5bd3" stroke-width="4" stroke-linecap="round">
          <path d="M10 60 C 30 30, 50 90, 70 60 S 90 30, 110 60"/>
        </g>
      </symbol>
    </defs>
  </svg>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
