{"path":"assets/css/styles.css","content":"/* Core styles for sound bath site */
:root{
  --bg:#fbfafc; --muted:#6f6b79; --accent:#6d5bd3; --accent-2:#8f7df0; --card:#ffffff; --glass:rgba(255,255,255,0.6);
  --radius:10px; --container:1100px; --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#2a2832;background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--container);margin:0 auto;padding:2rem}
.skip{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.8),transparent);backdrop-filter:blur(6px);border-bottom:1px solid rgba(30,30,30,0.03)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;padding:1rem}
.brand{display:flex;gap:0.75rem;align-items:center}
.brand svg{border-radius:8px}
.brand .name{display:block}
.main-nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
.main-nav .btn-cta{background:var(--accent);color:#fff;padding:0.5rem 0.8rem;border-radius:8px;text-decoration:none}
.hero{padding:4rem 0;background-image:url('/assets/img/pattern.svg');background-repeat:no-repeat;background-position:top right;background-size:35%}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:2rem;align-items:start}
.hero-copy h1{font-size:2rem;margin:0 0 0.5rem}
.lead{color:var(--muted);margin-top:0}
.hero-ctas{display:flex;gap:0.5rem;margin:1rem 0}
.btn{padding:0.6rem 0.9rem;border-radius:8px;background:transparent;border:1px solid var(--accent);color:var(--accent);text-decoration:none;cursor:pointer}
.btn:hover{opacity:0.95}
.btn.solid{background:var(--accent);color:#fff;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.card{background:var(--card);padding:1rem;border-radius:var(--radius);box-shadow:0 6px 18px rgba(30,30,60,0.06)}
.next-event .link{display:inline-block;margin-top:0.5rem;color:var(--accent)}
.disclaimer{font-size:0.85rem;color:#7a7584;margin-top:1rem}
.diagnostic, .plan, .micro-habits, .pricing, .cta{padding:3rem 0}
.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;align-items:start}
.price .amount{font-size:1.25rem;color:var(--accent);margin:0.5rem 0}
.price.highlight{border:2px solid rgba(109,91,211,0.12)}
.habits{list-style:none;padding:0;display:flex;gap:1rem}
.habits li{background:linear-gradient(180deg,#fff,#fbfaff);padding:0.6rem;border-radius:8px}
.cta-wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem}
.cta-actions .btn{margin-right:0.5rem}
.site-footer{padding:2rem 0;border-top:1px solid rgba(30,30,30,0.04);font-size:0.9rem}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.link{color:var(--accent);text-decoration:none}
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(10,10,15,0.35);padding:2rem}
.modal[aria-hidden="false"]{display:flex}
.modal-shell{background:var(--card);padding:1.25rem;border-radius:12px;max-width:560px;width:100;box-shadow:0 20px 50px rgba(15,12,30,0.25)}
.modal-close{position:absolute;right:1.5rem;top:1.5rem;background:none;border:0;font-size:1.25rem}
.modal-controls{display:flex;gap:0.5rem;margin:0.5rem 0}
.exercise-area{min-height:80px;padding:0.75rem;border-radius:8px;background:linear-gradient(180deg,#fff,#fbfaff);margin-top:0.5rem}
.modal-actions{display:flex;gap:0.5rem;justify-content:flex-end;margin-top:1rem}
/* reveal animation */
.reveal{opacity:0;transform:translateY(16px);transition:opacity 520ms ease,var(--transform) 520ms ease}
.reveal.visible{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
}
/* responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .plan-grid,.pricing-grid{grid-template-columns:1fr}
  .footer-grid{flex-direction:column;gap:1rem}
}
/* pattern fallback for environments that don't render external SVG */
body{background-color:var(--bg)}
"} 
{"path":"assets/js/main.js","content":"// Main JS: guided exercise modal & reveal-on-scroll & simple events module
(function(){
  // Utility: prefers reduced motion
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Scroll-triggered reveal
  function setupReveal(){
    var els = document.querySelectorAll('[data-reveal]');
    if(reduced){
      els.forEach(function(el){el.classList.add('visible');});
      return;
    }
    var obs = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){
          e.target.classList.add('visible');
          obs.unobserve(e.target);
        }
      });
    },{threshold:0.12});
    els.forEach(function(el){obs.observe(el);});
  }
  // Guided exercise modal
  var tryBtn = document.getElementById('tryNowBtn');
  var modal = document.getElementById('exerciseModal');
  var closeBtn = document.getElementById('exerciseClose');
  var cancelBtn = document.getElementById('exerciseCancel');
  var startBtn = document.getElementById('exerciseStart');
  var options = document.querySelectorAll('.exercise-option');
  var selectedMode = 'breath';
  var exerciseArea = document.getElementById('exerciseArea');

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    // Focus management
    modal.querySelector('.modal-shell').focus();
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    tryBtn.focus();
    exerciseArea.innerHTML = '';
  }
  if(tryBtn){tryBtn.addEventListener('click',openModal)}
  if(closeBtn){closeBtn.addEventListener('click',closeModal)}
  if(cancelBtn){cancelBtn.addEventListener('click',closeModal)}

  options.forEach(function(opt){
    opt.addEventListener('click',function(){
      options.forEach(function(o){o.classList.remove('active')});
      opt.classList.add('active');
      selectedMode = opt.getAttribute('data-mode');
    });
  });

  function breathingSequence(){
    var steps = [];
    // 2 minute gentle cycle: 4s inhale, 6s exhale, 3 rounds
    for(var i=0;i<3;i++){
      steps.push({text:'Breathe in — slow (4s)',dur:4000});
      steps.push({text:'Breathe out — slow (6s)',dur:6000});
    }
    return runSteps(steps,3000);
  }

  function journalingSequence(){
    var prompts = [
      'What is one small need I have right now?',
      'What felt heavy today that I can set down?',
      'Name one thing I can do to be kinder to myself tomorrow.'
    ];
    var i=0;
    exerciseArea.innerHTML = '<ol>' + prompts.map(function(p){return '<li>'+escapeHtml(p)+'</li>';}).join('') + '</ol>';
    // no timers; let user reflect; return resolved promise
    return Promise.resolve();
  }

  function intentionSequence(){
    var steps = [
      {text:'Settle into a comfortable seat. Close your eyes if safe.',dur:3000},
      {text:'Bring to mind one intention that feels honest and simple.',dur:5000},
      {text:'Repeat it silently three times. Hold the tone.',dur:4000},
      {text:'Open your eyes and keep the intention with you.',dur:2000}
    ];
    return runSteps(steps,5000);
  }

  function escapeHtml(str){return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

  function runSteps(steps,finalPause){
    exerciseArea.innerHTML = '<div class="running"></div>';
    var container = exerciseArea.querySelector('.running');
    var idx = 0;
    return new Promise(function(resolve){
      function next(){
        if(idx>=steps.length){
          container.textContent = 'Complete.';
          setTimeout(resolve, finalPause||1200);
          return;
        }
        var s = steps[idx++];
        container.textContent = s.text;
        setTimeout(next, s.dur);
      }
      next();
    });
  }

  startBtn.addEventListener('click',function(){
    startBtn.disabled = true;
    exerciseArea.innerHTML = '';
    var promise;
    if(selectedMode==='breath'){exerciseArea.innerHTML = ''; promise = breathingSequence();}
    else if(selectedMode==='journal'){promise = journalingSequence();}
    else {promise = intentionSequence();}
    promise.then(function(){startBtn.disabled=false});
  });

  // Simple diagnostic choices
  var choices = document.querySelectorAll('.choice');
  var diag = document.getElementById('diagnosticResult');
  choices.forEach(function(b){b.addEventListener('click',function(){
    var c = b.getAttribute('data-choice');
    if(c==='reset'){
      diag.textContent = 'Recommended: Community Series for a full transition and a short one-on-one if you need a focused check-in.';
    } else if(c==='focus'){
      diag.textContent = 'Recommended: Focused Session to anchor attention and create a practical practice plan.';
    } else if(c==='sleep'){
      diag.textContent = 'Recommended: A late-evening short gathering or private session with emphasis on soft return and breathwork.';
    }
  })});

  // Next-event module & simple calendar list (mock data)
  var events = [
    {id:1,title:'Evening Short-Form',date:'2026-03-01T19:00:00',location:'Studio A',excerpt:'A 50-minute group shape—arrive 10 minutes early.'},
    {id:2,title:'Midday Pause',date:'2026-03-05T12:30:00',location:'Studio B',excerpt:'A quick restorative practice for the workday.'},
    {id:3,title:'Private Focus',date:'2026-03-06T09:00:00',location:'Private Room',excerpt:'One-on-one session focusing on intention-setting.'}
  ];
  function renderNextEvent(){
    var el = document.getElementById('nextEventContent');
    if(!el) return;
    var now = new Date();
    var next = events.find(function(e){return new Date(e.date) > now;}) || events[0];
    var d = new Date(next.date);
    el.innerHTML = '<strong>'+escapeHtml(next.title)+'</strong><div class="meta">'+d.toLocaleString()+' • '+escapeHtml(next.location)+'</div><p>'+escapeHtml(next.excerpt)+'</p><details id="calList"><summary>Full calendar</summary><ul>'+events.map(function(ev){var dd=new Date(ev.date);return '<li>'+dd.toLocaleDateString()+': '+escapeHtml(ev.title)+'</li>';}).join('')+'</ul></details>';
  }

  // keyboard: close modal on Esc
  document.addEventListener('keydown',function(e){if(e.key==='Escape'){if(modal.getAttribute('aria-hidden')==='false'){closeModal()}}});

  // init
  document.addEventListener('DOMContentLoaded',function(){setupReveal();renderNextEvent();});
})();"} 
